n, puis mélange-les avec l'oignon et l'ail revenus, les tomates et la cannelle.","timer":{"label":"Cuisson","min":20}},{"text":"Prépare la béchamel.","timer":null},{"text":"Monte la moussaka, termine par la béchamel et la feta émiettée, et enfourne 35 min.","timer":{"label":"Four","min":35}}]},{"title":"Wrap végétarien houmous et légumes","intro":"Un wrap coloré et rassasiant, au houmous.","minutes":20,"calories":400,"difficulty":"Facile","imageSearch":"hummus veggie wrap","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"galette de blé","plural":"galettes de blé","qty":4,"unit":"","have":false},{"name":"houmous","plural":"houmous","qty":8,"unit":"c. à s.","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"pousse d'épinard","plural":"pousses d'épinard","qty":60,"unit":"g","have":false},{"name":"feta","plural":"feta","qty":80,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais griller la courgette et le poivron en lanières dans l'huile 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Tartine les galettes de houmous.","timer":null},{"text":"Ajoute les épinards, les légumes grillés et la feta, puis roule.","timer":null}]},{"title":"Tomates farcies végétariennes","intro":"Des tomates farcies au riz et à la feta, à la grecque.","minutes":60,"calories":360,"difficulty":"Facile","imageSearch":"vegetarian stuffed tomatoes rice feta","veg":true,"oven":true,"cold":false,"missing":"","origin":"Inspiration grecque","serves":4,"items":[{"name":"tomate","plural":"tomates","qty":8,"unit":"","have":false},{"name":"riz","plural":"riz","qty":150,"unit":"g","have":false},{"name":"feta","plural":"feta","qty":100,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Vide les tomates et hache la pulpe.","timer":null},{"text":"Mélange le riz cru avec la pulpe, l'oignon haché, la feta, les herbes et l'huile.","timer":null},{"text":"Remplis les tomates aux trois quarts et range-les dans un plat avec 10 cl d'eau.","timer":null},{"text":"Enfourne 50 min.","timer":{"label":"Four","min":50}}]},{"title":"Shakshuka verte","intro":"Une shakshuka toute verte, à la feta.","minutes":25,"calories":300,"difficulty":"Facile","imageSearch":"green shakshuka spinach","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":6,"unit":"","have":false},{"name":"épinard","plural":"épinards","qty":300,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":1,"unit":"","have":false},{"name":"feta","plural":"feta","qty":80,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais fondre le poireau et la courgette en dés dans l'huile 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Ajoute l'ail, le cumin et les épinards jusqu'à ce qu'ils tombent.","timer":null},{"text":"Casse les œufs dans les légumes, couvre et cuis 6 min.","timer":{"label":"Cuisson","min":6}},{"text":"Parsème de feta.","timer":null}]},{"title":"Salade de lentilles, feta et légumes croquants","intro":"Une salade complète et colorée, idéale à emporter.","minutes":35,"calories":380,"difficulty":"Facile","imageSearch":"lentil feta salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lentille verte","plural":"lentilles vertes","qty":250,"unit":"g","have":false},{"name":"feta","plural":"feta","qty":100,"unit":"g","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":150,"unit":"g","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":0.5,"unit":"","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les lentilles 25 min et laisse-les refroidir.","timer":{"label":"Cuisson","min":25}},{"text":"Coupe le concombre, les tomates et l'oignon.","timer":null},{"text":"Mélange tout avec la feta émiettée, la menthe, le jus du citron, l'huile, sel et poivre.","timer":null}]}]$r$::jsonb, 'claude')
