insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('parmesan', 'parmesan', array[]::text[], 'list', $r$[{"title":"Spaghetti bolognaise","intro":"Une sauce tomate à la viande mijotée tranquillement, sur des spaghetti al dente.","minutes":50,"calories":620,"difficulty":"Facile","imageSearch":"spaghetti bolognese","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":400,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"origan","plural":"origan","qty":null,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":40,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon, la carotte en petits dés et l'ail dans l'huile 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute la viande et fais-la dorer 5 min en l'émiettant.","timer":{"label":"Cuisson","min":5}},{"text":"Verse les tomates, ajoute l'origan, sale et poivre, et laisse mijoter 30 min.","timer":{"label":"Mijotage","min":30}},{"text":"Fais cuire les spaghetti dans l'eau bouillante salée selon le paquet.","timer":{"label":"Pâtes","min":10}},{"text":"Sers la sauce sur les pâtes avec le parmesan.","timer":null}],"kids":true},{"title":"Boulettes de bœuf à la sauce tomate","intro":"Des boulettes moelleuses, mijotées dans une sauce tomate au basilic.","minutes":40,"calories":520,"difficulty":"Facile","imageSearch":"meatballs tomato sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"bœuf haché","plural":"bœuf haché","qty":500,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"chapelure","plural":"chapelure","qty":40,"unit":"g","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":30,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Mélange la viande avec l'œuf, la chapelure, le parmesan, la moitié de l'oignon haché, sel et poivre. Forme des boulettes.","timer":null},{"text":"Fais-les dorer dans l'huile 6 min. Réserve.","timer":{"label":"Poêle","min":6}},{"text":"Fais revenir le reste d'oignon et l'ail, ajoute les tomates et cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Remets les boulettes et laisse mijoter 15 min. Ajoute le basilic.","timer":{"label":"Mijotage","min":15}}],"kids":true},{"title":"Lasagnes à la bolognaise","intro":"Des couches de pâtes, de bolognaise et de béchamel, gratinées au parmesan.","minutes":90,"calories":680,"difficulty":"Moyen","imageSearch":"beef lasagna","veg":false,"oven":true,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"feuille de lasagne","plural":"feuilles de lasagne","qty":12,"unit":"","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":500,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"beurre","plural":"beurres","qty":50,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":50,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":70,"unit":"cl","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":60,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon et l'ail dans l'huile, ajoute la viande puis les tomates. Laisse mijoter 25 min.","timer":{"label":"Mijotage","min":25}},{"text":"Fais une béchamel : beurre fondu, farine, puis lait en fouettant 5 min. Sale et poivre.","timer":{"label":"Béchamel","min":5}},{"text":"Préchauffe le four à 180 °C. Dans un plat, alterne bolognaise, feuilles de lasagne et béchamel, sur 3 couches.","timer":null},{"text":"Termine par de la béchamel et le parmesan.","timer":null},{"text":"Enfourne 40 min.","timer":{"label":"Four","min":40}}],"kids":true},{"title":"Moussaka","intro":"Des couches d'aubergines, de viande d'agneau à la tomate et à la cannelle, sous une béchamel gratinée.","minutes":100,"calories":640,"difficulty":"Moyen","imageSearch":"greek moussaka","veg":false,"oven":true,"cold":false,"missing":"","origin":"Plat grec","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":3,"unit":"","have":false},{"name":"agneau haché","plural":"agneau haché","qty":500,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"cannelle","plural":"cannelle","qty":0.5,"unit":"c. à c.","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":40,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":5,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe les aubergines en tranches, badigeonne-les d'huile et fais-les rôtir 20 min au four à 200 °C.","timer":{"label":"Four","min":20}},{"text":"Fais revenir l'oignon, l'ail et la viande, ajoute les tomates et la cannelle, et laisse mijoter 20 min.","timer":{"label":"Mijotage","min":20}},{"text":"Prépare une béchamel avec le beurre, la farine et le lait, puis ajoute l'œuf battu.","timer":null},{"text":"Alterne aubergines et viande dans un plat, termine par la béchamel et le parmesan.","timer":null},{"text":"Enfourne 40 min à 180 °C.","timer":{"label":"Four","min":40}}]},{"title":"Risotto aux champignons","intro":"Un riz crémeux cuit doucement dans le bouillon, avec des champignons et du parmesan.","minutes":35,"calories":560,"difficulty":"Moyen","imageSearch":"mushroom risotto","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"riz arborio","plural":"riz arborio","qty":320,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":300,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":10,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":2,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":60,"unit":"g","have":false},{"name":"beur